BEGIN;
CREATE TABLE referral.relationships (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, referrer_user_id uuid NOT NULL REFERENCES identity.users(id), referred_user_id uuid NOT NULL REFERENCES identity.users(id), level smallint NOT NULL DEFAULT 1 CHECK(level>0), created_at timestamptz NOT NULL DEFAULT now(), CHECK(referrer_user_id<>referred_user_id), UNIQUE(tenant_id,referred_user_id,level));
CREATE TABLE referral.rules (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, level smallint NOT NULL CHECK(level>0), share_bps integer NOT NULL CHECK(share_bps BETWEEN 0 AND 10000), active boolean NOT NULL DEFAULT true, UNIQUE(tenant_id,level));
CREATE TABLE referral.distributions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), tenant_id uuid NOT NULL REFERENCES tenant.tenants(id) ON DELETE CASCADE, conversion_id uuid NOT NULL REFERENCES tracking.conversions(id), beneficiary_user_id uuid NOT NULL REFERENCES identity.users(id), level smallint NOT NULL CHECK(level>0), amount numeric(20,8) NOT NULL CHECK(amount>=0), currency char(3) NOT NULL, ledger_transaction_id uuid, UNIQUE(conversion_id,beneficiary_user_id,level));
COMMIT;
